//! `PKT-376`: `StructureCollapseUpdate` against vectors from the unmodified
//! reference (`docs/golden_vectors/StructureCollapseUpdate.json`, generated by
//! `tests/cpp_harness/gen_structure_collapse_update.cpp`).

use zh_common::crc::Crc;
use zh_common::golden_json::{get_str, get_u32};
use zh_common::ini::{IniLoadType, IniReader};
use zh_common::math::{Coord3D, Matrix3D, Region3D};
use zh_common::types::{Bool, Int, TeamId, UpdateSleepTime, VeterancyLevel, FALSE, TRUE};
use zh_common::xfer::{XferCrc, XferLoad, XferSave};
use zh_logic::arena::{FacetMask, ModuleSlot, ObjectSlot};
use zh_logic::combat::damage::DamageInfo;
use zh_logic::modules::module::{BehaviorModule, ModuleType};
use zh_logic::modules::update::structure_collapse_update::{
    StructureCollapseUpdate, COLLAPSESTATE_COLLAPSING, COLLAPSESTATE_DONE, COLLAPSESTATE_STANDING,
};
use zh_logic::object::thing::{make_align_to_normal_matrix, ThingTerrainAccess};
use zh_logic::pathfinder::pathfind_constants::PathfindLayerEnum;
use zh_logic::rules::combat_types::{DamageType, DeathType};
use zh_logic::rules::model_state::ModelConditionFlagType;
use zh_logic::rules::object_status_types::ObjectStatusType;
use zh_logic::scheduler::UPDATE_SLEEP_FOREVER;
use zh_logic::sim::{RulesRegistry, SimApi, SimContext, SimView, SimWorld};

const TEAM_NEUTRAL: TeamId = TeamId(3);
const TEAM_A: TeamId = TeamId(1);
const TEAM_B: TeamId = TeamId(2);
const PLAYER_TEAMS: [&[TeamId]; 3] = [&[TEAM_NEUTRAL], &[TEAM_A], &[TEAM_B]];

const FX_NAMES: [&str; 8] = [
    "SC_FX_I0", "SC_FX_I1", "SC_FX_D0", "SC_FX_D1", "SC_FX_B0", "SC_FX_B1", "SC_FX_F0", "SC_FX_F1",
];
const OCL_NAMES: [&str; 8] = [
    "SC_OCL_I0",
    "SC_OCL_I1",
    "SC_OCL_D0",
    "SC_OCL_D1",
    "SC_OCL_B0",
    "SC_OCL_B1",
    "SC_OCL_F0",
    "SC_OCL_F1",
];

fn golden() -> &'static str {
    include_str!("../../../docs/golden_vectors/StructureCollapseUpdate.json")
}

struct SlopeTerrain;

impl ThingTerrainAccess for SlopeTerrain {
    fn get_ground_height(&self, x: f32, y: f32, normal: Option<&mut Coord3D>) -> f32 {
        if let Some(n) = normal {
            *n = Coord3D::new(0.0, 0.0, 1.0);
        }
        x * 0.01 + y * 0.02
    }

    fn align_on_terrain(
        &self,
        angle: f32,
        pos: &Coord3D,
        stick_to_ground: Bool,
        mtx: &mut Matrix3D,
    ) -> PathfindLayerEnum {
        let mut pos = *pos;
        if stick_to_ground != FALSE {
            pos.z = self.get_ground_height(pos.x, pos.y, None);
        }
        make_align_to_normal_matrix(angle, &pos, &Coord3D::new(0.0, 0.0, 1.0), mtx);
        PathfindLayerEnum::Ground
    }

    fn is_underwater(
        &self,
        _x: f32,
        _y: f32,
        _water_z: Option<&mut f32>,
        _terrain_z: Option<&mut f32>,
    ) -> Bool {
        FALSE
    }
}

fn fixture_text() -> String {
    let line = golden()
        .lines()
        .find(|l| l.starts_with("\"ini\":\""))
        .expect("ini line");
    line["\"ini\":\"".len()..line.rfind('"').expect("quote")].replace("\\n", "\n")
}

fn build_rules(ini: &str) -> RulesRegistry {
    let mut rules = RulesRegistry::new();
    for name in FX_NAMES {
        rules.fx_list_names.insert(name.to_owned());
    }
    for name in OCL_NAMES {
        rules.ocl_names.insert(name.to_owned());
    }
    let mut reader = IniReader::new("scu.ini", ini.as_bytes(), IniLoadType::Overwrite);
    rules
        .load_thing_templates_from_ini(&mut reader)
        .expect("objects");
    rules.thing_factory.post_process_load();
    rules
}

fn new_world(frame: u32, seed: u32) -> SimWorld {
    let mut world = SimWorld::new();
    world.frame = frame;
    world.next_object_id = 1;
    world.rng.init_random_with_seed(seed);
    world
}

fn setup_teams(sim: &mut SimContext) {
    sim.init_partition(
        20.0,
        Region3D {
            lo: Coord3D::new(0.0, 0.0, 0.0),
            hi: Coord3D::new(1000.0, 1000.0, 100.0),
        },
    );
    for (player, &teams) in PLAYER_TEAMS.iter().enumerate() {
        sim.world
            .player_default_teams
            .insert(player as Int, teams[0]);
        for &team in teams {
            sim.add_player_team(team, player as Int);
        }
    }
}

fn spawn(sim: &mut SimContext, name: &str, team: TeamId, pos: Coord3D, angle: f32) -> ObjectSlot {
    let tid = sim
        .rules
        .thing_factory
        .find_template_id(name)
        .unwrap_or_else(|| panic!("missing template {name}"));
    let slot = sim.spawn_object(tid, team, Coord3D::default(), 0.0);
    sim.set_object_position(slot, &pos);
    sim.set_object_orientation(slot, angle);
    slot
}

fn find_module(sim: &mut SimContext, owner: ObjectSlot, name: &str) -> Option<ModuleSlot> {
    let key = sim.rules.name_keys.name_to_key(name);
    let obj = sim.world.objects.get(owner).expect("object");
    obj.behaviors.iter().map(|&(ms, _)| ms).find(|&ms| {
        sim.world
            .modules
            .payload(ms)
            .is_some_and(|p| p.module_name_key() == key)
    })
}

fn next_call_frame(sim: &SimContext, slot: ModuleSlot) -> u32 {
    sim.module_schedule(slot)
        .expect("schedule")
        .next_call_frame()
}

fn update(sim: &mut SimContext, m: ModuleSlot) -> UpdateSleepTime {
    sim.dispatch_module(m, |b, s, c| b.as_update_mut().expect("update").update(s, c))
        .expect("dispatch")
}

fn step(sim: &mut SimContext, m: ModuleSlot, frame: u32) {
    sim.world.frame = frame;
    if next_call_frame(sim, m) > frame {
        return;
    }
    let sleep = update(sim, m);
    let sleep = if sleep.0 < 1 {
        UpdateSleepTime::NONE
    } else {
        sleep
    };
    let next = frame.saturating_add(sleep.0).min(UPDATE_SLEEP_FOREVER);
    sim.world
        .modules
        .meta_mut(m)
        .schedule
        .set_next_call_frame(next);
    let index = sim.world.modules.meta(m).schedule.index_in_logic();
    if index >= 0 {
        sim.world
            .sleepy_updates
            .rebalance(&mut sim.world.modules, index as usize);
    }
}

fn save_bytes(sim: &mut SimContext, slot: ModuleSlot) -> (Vec<u8>, u32) {
    let (mut payload, _ctx, generation) = sim.world.modules.take_payload(slot).expect("payload");
    let mut xs = XferSave::new();
    payload.xfer(&mut xs, sim).expect("xfer save");
    let mut xc = XferCrc::new();
    payload.crc(&mut xc);
    sim.world.modules.restore_payload(slot, generation, payload);
    (xs.as_bytes().to_vec(), xc.get_crc())
}

fn crc_of(bytes: &[u8]) -> u32 {
    let mut crc = Crc::new();
    crc.compute_crc(bytes, bytes.len() as i32);
    crc.get()
}

fn check_load(sim: &mut SimContext, slot: ModuleSlot, bytes: &[u8]) {
    let mut copy = sim
        .world
        .modules
        .payload(slot)
        .and_then(|p| p.as_any())
        .and_then(|a| a.downcast_ref::<StructureCollapseUpdate>())
        .expect("StructureCollapseUpdate")
        .clone();
    copy.collapse_frame = 999;
    copy.burst_frame = 888;
    copy.collapse_state = COLLAPSESTATE_DONE;
    copy.collapse_velocity = 7.5;
    copy.current_height = -3.5;
    let mut load = XferLoad::new(bytes);
    copy.xfer(&mut load, sim).expect("load");
    let mut again = XferSave::new();
    copy.xfer(&mut again, sim).expect("resave");
    assert_eq!(again.as_bytes(), bytes);
}

fn matrix_of(sim: &SimContext, o: ObjectSlot) -> String {
    let m = sim
        .world
        .objects
        .get(o)
        .expect("object")
        .thing
        .get_transform_matrix();
    m.rows
        .iter()
        .flatten()
        .map(|v| v.to_bits().to_string())
        .collect::<Vec<_>>()
        .join(",")
}

fn condition(sim: &SimContext, o: ObjectSlot, flag: ModelConditionFlagType) -> u8 {
    let obj = sim.world.objects.get(o).expect("object");
    u8::from(obj.model_condition.test(flag.as_i32()) != FALSE)
}

fn dead(sim: &SimContext, o: ObjectSlot) -> u8 {
    u8::from(
        sim.world
            .objects
            .get(o)
            .expect("object")
            .is_effectively_dead()
            != FALSE,
    )
}

fn joined(items: Vec<String>) -> String {
    if items.is_empty() {
        "-".to_string()
    } else {
        items.concat()
    }
}

fn point(p: &Coord3D) -> String {
    format!("{},{},{}", p.x.to_bits(), p.y.to_bits(), p.z.to_bits())
}

fn take_fx(sim: &mut SimContext) -> String {
    joined(
        sim.world
            .triggered_fx_lists
            .drain(..)
            .map(|(name, pos)| {
                let list = FX_NAMES.iter().position(|&n| n == name).expect("FX name");
                format!("{list},{};", point(&pos))
            })
            .collect(),
    )
}

fn take_ocl(sim: &mut SimContext) -> String {
    joined(
        sim.world
            .spawned_ocls
            .drain(..)
            .map(|(name, _, pos, _)| {
                let list = OCL_NAMES.iter().position(|&n| n == name).expect("OCL name");
                format!("{list},{};", point(&pos))
            })
            .collect(),
    )
}

fn row_of(
    sim: &mut SimContext,
    o: ObjectSlot,
    m: ModuleSlot,
    bfx: Option<ModuleSlot>,
    ret: u32,
) -> String {
    let (bytes, mod_crc) = save_bytes(sim, m);
    let save_crc = crc_of(&bytes);
    let hex: String = bytes.iter().map(|b| format!("{b:02x}")).collect();
    check_load(sim, m, &bytes);
    let scu = sim
        .world
        .modules
        .payload(m)
        .and_then(|p| p.as_any())
        .and_then(|a| a.downcast_ref::<StructureCollapseUpdate>())
        .expect("StructureCollapseUpdate");
    let decoded = format!(
        "{},{},{},{},{}",
        scu.collapse_frame,
        scu.burst_frame,
        scu.collapse_state,
        scu.collapse_velocity.to_bits(),
        scu.current_height.to_bits()
    );
    let bfx_crc = bfx.map_or(0, |b| {
        let (b_bytes, _) = save_bytes(sim, b);
        crc_of(&b_bytes)
    });
    let next_call = next_call_frame(sim, m);
    let matrix = matrix_of(sim, o);
    let flags = format!(
        "{}{}{}",
        dead(sim, o),
        condition(sim, o, ModelConditionFlagType::Rubble),
        condition(sim, o, ModelConditionFlagType::PostCollapse)
    );
    let seed = sim.world.rng.get_game_logic_random_seed_crc();
    let client_probe = sim.world.rng.get_game_client_random_value(0, 1_000_000);
    let fx = take_fx(sim);
    let ocl = take_ocl(sim);
    format!(
        "{hex} {save_crc} {mod_crc} {ret} {next_call} {decoded} {matrix} {flags} {bfx_crc} {seed} {client_probe} {fx} {ocl}"
    )
}

fn between<'a>(line: &'a str, start: &str, end: &str) -> &'a str {
    let rest = &line[line.find(start).expect(start) + start.len()..];
    &rest[..rest.find(end).expect(end)]
}

struct Vector<'a> {
    line: &'a str,
    index: usize,
}

impl Vector<'_> {
    fn num(&self, key: &str) -> u32 {
        get_u32(self.line, key).unwrap_or_else(|| panic!("vector {} lacks {key}", self.index))
    }

    fn real(&self, key: &str) -> f32 {
        f32::from_bits(self.num(key))
    }

    fn pos(&self) -> Coord3D {
        Coord3D::new(self.real("x"), self.real("y"), self.real("z"))
    }

    fn ops(&self) -> Vec<[u32; 4]> {
        let numbers: Vec<u32> = between(self.line, "\"ops\":[", "],\"rows\"")
            .split(['[', ']', ','])
            .filter(|t| !t.is_empty())
            .map(|t| t.parse().expect("op number"))
            .collect();
        numbers
            .chunks_exact(4)
            .map(|c| c.try_into().expect("four"))
            .collect()
    }

    fn rows(&self) -> Vec<&str> {
        between(self.line, "\"rows\":[\"", "\"],\"client\"")
            .split("\",\"")
            .collect()
    }

    fn check(&self, what: &str, got: &str, want: &str) {
        assert_eq!(got, want, "vector {} {what}", self.index);
    }
}

#[test]
fn oracle_structure_and_source_sha256() {
    let doc = golden();
    assert!(doc.contains("\"packet\":\"PKT-376\""));
    assert!(doc.contains("\"module\":\"StructureCollapseUpdate\""));
    assert!(doc.contains("\"vector_count\":240"));
    assert!(doc.contains("21fbe725e7bf4f57c7d327655b75d5dccd7ade9411e36dbb08873fadf196b00a"));
    assert!(doc.contains("8662d877461d3f485a3cf55d3ddceb32a68fb53fd5c015319760b3cd9dda1cb2"));
    let count = doc
        .lines()
        .filter(|l| l.starts_with("{\"variant\":"))
        .count();
    assert_eq!(count, 240);
}

#[test]
fn structure_collapse_update_matches_reference() {
    let lines: Vec<&str> = golden()
        .lines()
        .map(|l| l.trim_end_matches(','))
        .filter(|l| l.starts_with("{\"variant\":"))
        .collect();
    assert_eq!(lines.len(), 240);

    let mut sim = SimContext::new();
    sim.rules = build_rules(&fixture_text());
    sim.terrain = Box::new(SlopeTerrain);

    let mut total_ops = 0usize;
    for (index, &line) in lines.iter().enumerate() {
        let v = Vector { line, index };
        sim.world = new_world(v.num("frame"), v.num("seed"));
        setup_teams(&mut sim);
        sim.rules.global_data.gravity = v.real("gravity");

        let o = spawn(
            &mut sim,
            &format!("SC_V{}", v.num("variant")),
            TEAM_A,
            v.pos(),
            v.real("angle"),
        );
        let m =
            find_module(&mut sim, o, "StructureCollapseUpdate").expect("StructureCollapseUpdate");
        let bfx = find_module(&mut sim, o, "BoneFXUpdate");

        let spawn_row = row_of(&mut sim, o, m, bfx, 0);
        v.check(
            "spawn",
            &spawn_row,
            get_str(v.line, "spawn").expect("spawn"),
        );

        let ops = v.ops();
        let rows = v.rows();
        assert_eq!(ops.len(), rows.len(), "vector {index}");

        let mut frame = v.num("frame");
        for (k, (op, want)) in ops.iter().zip(&rows).enumerate() {
            let mut ret = 0;
            sim.world.frame = frame;
            match op[0] {
                0 => {
                    let mut info = DamageInfo::default();
                    info.input.damage_type =
                        DamageType::from_i32(op[1] as i32).expect("damage type");
                    info.input.death_type = DeathType::from_i32(op[2] as i32).expect("death type");
                    info.input.amount = op[3] as f32;
                    sim.attempt_damage(o, &mut info);
                }
                1 => {
                    for _ in 0..op[1] {
                        frame += 1;
                        step(&mut sim, m, frame);
                    }
                }
                2 => {
                    ret = update(&mut sim, m).0;
                }
                3 => {
                    let mut info = DamageInfo::default();
                    info.input.damage_type =
                        DamageType::from_i32(op[1] as i32).expect("damage type");
                    info.input.death_type = DeathType::from_i32(op[2] as i32).expect("death type");
                    info.input.amount = 100.0;
                    sim.dispatch_module(m, |b, s, c| {
                        b.as_die_mut().expect("die").on_die(s, c, &info);
                    })
                    .expect("dispatch");
                }
                4 => {
                    let status = ObjectStatusType::from_i32(op[1] as i32).expect("status");
                    if op[2] != 0 {
                        sim.set_status(o, status);
                    } else {
                        sim.clear_status(o, status);
                    }
                }
                5 => {
                    let vet = VeterancyLevel::from_i32(op[1] as i32);
                    sim.set_veterancy_level(o, vet, FALSE, FALSE);
                }
                6 => {
                    frame += op[1];
                    sim.world.frame = frame;
                    ret = update(&mut sim, m).0;
                }
                _ => {
                    frame += 1;
                    step(&mut sim, bfx.expect("BoneFXUpdate"), frame);
                }
            }
            let got = row_of(&mut sim, o, m, bfx, ret);
            v.check(&format!("op {k} {op:?}"), &got, want);
            total_ops += 1;
        }
        let client = sim.rng_client_int(0, 1_000_000);
        v.check(
            "client seed",
            &client.to_string(),
            &v.num("client").to_string(),
        );
    }
    assert!(total_ops > 1000, "too few ops: {total_ops}");
}

#[test]
fn descriptor_deselection_bone_fx_stops_and_load_post_process() {
    let mut sim = SimContext::new();
    sim.rules = build_rules(&fixture_text());
    sim.terrain = Box::new(SlopeTerrain);
    sim.world = new_world(50, 777);
    setup_teams(&mut sim);

    let desc = sim
        .rules
        .module_registry
        .find_descriptor("StructureCollapseUpdate", ModuleType::Behavior)
        .expect("descriptor");
    assert_eq!(desc.facet_mask, FacetMask(0x003));
    assert!(desc.create_module.is_some());

    // Deselect & BoneFX stop assertions on V3 (has BoneFXUpdate), plus ignored die on V4.
    let v4 = spawn(
        &mut sim,
        "SC_V4",
        TEAM_A,
        Coord3D::new(400.0, 400.0, 0.0),
        0.0,
    );
    let m4 = find_module(&mut sim, v4, "StructureCollapseUpdate").expect("m4");
    let mut dmg_bad = DamageInfo::default();
    dmg_bad.input.damage_type = DamageType::Explosion;
    dmg_bad.input.death_type = DeathType::Crushed;
    sim.dispatch_module(m4, |b, s, c| {
        assert_eq!(
            b.as_die().expect("die").is_die_applicable(s, c, &dmg_bad),
            FALSE
        );
        b.as_die_mut().expect("die").on_die(s, c, &dmg_bad);
    })
    .expect("dispatch");
    assert!(sim.world.deselected_objects.is_empty());

    let v3 = spawn(
        &mut sim,
        "SC_V3",
        TEAM_A,
        Coord3D::new(450.0, 450.0, 0.0),
        0.5,
    );
    let v3_id = sim.world.objects.get(v3).expect("v3").id;
    let m3 = find_module(&mut sim, v3, "StructureCollapseUpdate").expect("m3");
    let mut dmg_ok = DamageInfo::default();
    dmg_ok.input.damage_type = DamageType::Explosion;
    dmg_ok.input.death_type = DeathType::Normal;
    dmg_ok.input.amount = 1000.0;
    sim.attempt_damage(v3, &mut dmg_ok);
    assert_eq!(sim.world.deselected_objects, vec![(v3_id, 0xffff, TRUE)]);
    assert!(sim.world.bone_fx_stops.is_empty());

    let mut frame = 50;
    for _ in 0..30 {
        if sim
            .world
            .modules
            .payload(m3)
            .and_then(|p| p.as_any())
            .and_then(|a| a.downcast_ref::<StructureCollapseUpdate>())
            .expect("scu")
            .collapse_state
            == COLLAPSESTATE_DONE
        {
            break;
        }
        frame += 1;
        step(&mut sim, m3, frame);
    }
    assert_eq!(
        sim.world
            .modules
            .payload(m3)
            .and_then(|p| p.as_any())
            .and_then(|a| a.downcast_ref::<StructureCollapseUpdate>())
            .expect("scu")
            .collapse_state,
        COLLAPSESTATE_DONE
    );
    assert_eq!(sim.world.bone_fx_stops, vec![v3_id]);

    // Verify `load_post_process` rebinds module slot and restores schedule state.
    let v0 = spawn(
        &mut sim,
        "SC_V0",
        TEAM_A,
        Coord3D::new(500.0, 500.0, 0.0),
        0.0,
    );
    let m0 = find_module(&mut sim, v0, "StructureCollapseUpdate").expect("m0");
    sim.dispatch_module(m0, |b, s, c| {
        assert_eq!(
            b.as_update_mut().expect("update").update(s, c),
            UpdateSleepTime::FOREVER
        );
    })
    .expect("dispatch");
    sim.dispatch_module(m0, |b, s, c| {
        b.as_die_mut().expect("die").on_die(s, c, &dmg_ok);
    })
    .expect("dispatch");
    let (saved, _) = save_bytes(&mut sim, m0);
    let mut reloaded = sim
        .world
        .modules
        .payload(m0)
        .and_then(|p| p.as_any())
        .and_then(|a| a.downcast_ref::<StructureCollapseUpdate>())
        .expect("scu")
        .clone();
    reloaded.collapse_state = COLLAPSESTATE_STANDING;
    reloaded.schedule.mod_slot = None;
    let mut load = XferLoad::new(&saved);
    reloaded.xfer(&mut load, &sim).expect("load");
    let ctx0 = sim.world.modules.meta(m0).context(m0);
    reloaded.load_post_process(&mut sim, ctx0);
    assert_eq!(reloaded.schedule.mod_slot, Some(m0));
    assert_ne!(reloaded.collapse_state, COLLAPSESTATE_STANDING);
    assert_eq!(COLLAPSESTATE_COLLAPSING, 2);
}

#[test]
fn marks_ai_dead_and_resets_orientation_on_completion() {
    let ini = "\
Object SC_AI
  KindOf = PRELOAD STRUCTURE
  Geometry = BOX
  GeometryMajorRadius = 5.0
  GeometryMinorRadius = 5.0
  GeometryHeight = 0.0
  Body = ActiveBody ModuleTag_Body
    MaxHealth = 100.0
    InitialHealth = 100.0
  End
  Behavior = AIUpdateInterface ModuleTag_AI
  End
  Behavior = StructureCollapseUpdate ModuleTag_Collapse
    MinCollapseDelay = 0
    MaxCollapseDelay = 0
  End
End
";
    let mut sim = SimContext::new();
    sim.rules = build_rules(ini);
    sim.terrain = Box::new(SlopeTerrain);
    sim.world = new_world(10, 42);
    setup_teams(&mut sim);

    let o = spawn(
        &mut sim,
        "SC_AI",
        TEAM_A,
        Coord3D::new(200.0, 200.0, 0.0),
        0.7,
    );
    let m = find_module(&mut sim, o, "StructureCollapseUpdate").expect("scu");
    let mut tilted = *sim
        .world
        .objects
        .get(o)
        .expect("obj")
        .thing
        .get_transform_matrix();
    tilted.in_place_pre_rotate_x(0.4);
    sim.set_object_transform_matrix(o, &tilted);
    assert_ne!(
        sim.world
            .objects
            .get(o)
            .expect("obj")
            .thing
            .get_transform_matrix()
            .rows[2][2],
        1.0
    );
    assert_eq!(sim.world.objects.get(o).expect("obj").ai_dead, FALSE);

    let mut dmg = DamageInfo::default();
    dmg.input.damage_type = DamageType::Explosion;
    dmg.input.death_type = DeathType::Normal;
    dmg.input.amount = 500.0;
    sim.attempt_damage(o, &mut dmg);
    assert_eq!(sim.world.objects.get(o).expect("obj").ai_dead, TRUE);

    sim.world.frame = 11;
    let sleep = update(&mut sim, m);
    assert_eq!(sleep, UpdateSleepTime::FOREVER);
    assert_eq!(
        sim.world
            .objects
            .get(o)
            .expect("obj")
            .thing
            .get_transform_matrix()
            .rows[2][2],
        1.0
    );
}
